class Vehiculo:
    def __init__(self, marca: str, velocidad_max: float):
        self.marca = marca
        self.velocidad_max = velocidad_max
        self._velocidad = 0.0

    def acelerar(self, delta: float) -> None:
        self._velocidad = min(self._velocidad + delta, self.velocidad_max)

    def frenar(self, delta: float) -> None:
        self._velocidad = max(self._velocidad - delta, 0)

    @property
    def velocidad(self) -> float:
        return self._velocidad

    def __str__(self) -> str:
        return f"{self.marca} a {self._velocidad:.1f} km/h"

auto = Vehiculo("Toyota", 200)
auto.acelerar(80)
auto.acelerar(80)
print(auto)        # Toyota a 160.0 km/h

class Punto:
    def __init__(self, x: float, y: float):
        self.x = x
        self.y = y

    def __add__(self, otro: "Punto") -> "Punto":
        return Punto(self.x + otro.x, self.y + otro.y)

    def __eq__(self, otro: object) -> bool:
        if not isinstance(otro, Punto):
            return NotImplemented
        return self.x == otro.x and self.y == otro.y

    def __repr__(self) -> str:
        return f"Punto({self.x}, {self.y})"

p1 = Punto(1, 2)
p2 = Punto(3, 4)
print(p1 + p2)  # Punto(4, 6)

from dataclasses import dataclass, field
from typing import List

@dataclass
class Producto:
    nombre: str
    precio: float
    tags: List[str] = field(default_factory=list)

    @property
    def precio_con_iva(self) -> float:
        return self.precio * 1.21

p = Producto("Laptop", 999.99, ["electrónica", "computación"])
print(p.precio_con_iva)
print(p)

class Circulo:
    PI = 3.14159

    def __init__(self, radio: float):
        self.radio = radio

    @property
    def area(self) -> float:
        return self.PI * self.radio ** 2

    @property
    def perimetro(self) -> float:
        return 2 * self.PI * self.radio

c = Circulo(5)
print(f"Área: {c.area:.2f}")
print(f"Perímetro: {c.perimetro:.2f}")

class Contador:
    _instancias = 0

    def __init__(self):
        Contador._instancias += 1
        self.id = Contador._instancias

    @classmethod
    def total(cls) -> int:
        return cls._instancias

    @staticmethod
    def descripcion() -> str:
        return "Clase Contador"

a = Contador()
b = Contador()
print(Contador.total())       # 2
print(Contador.descripcion()) # Clase Contador

class Pila:
    def __init__(self):
        self._items: list = []

    def push(self, item) -> None:
        self._items.append(item)

    def pop(self):
        if not self._items:
            raise IndexError("Pila vacía")
        return self._items.pop()

    def peek(self):
        if not self._items:
            raise IndexError("Pila vacía")
        return self._items[-1]

    def __len__(self) -> int:
        return len(self._items)

    def __bool__(self) -> bool:
        return bool(self._items)

p = Pila()
p.push(1)
p.push(2)
print(p.pop())   # 2
print(len(p))    # 1

class Perro:
    def __init__(self, nombre: str, raza: str):
        self.nombre = nombre
        self.raza = raza

    def ladrar(self) -> str:
        return f"{self.nombre} dice: ¡Guau!"

    def __repr__(self) -> str:
        return f"Perro({self.nombre!r}, {self.raza!r})"

fido = Perro("Fido", "Labrador")
print(fido.ladrar())
print(fido)

class Temperatura:
    def __init__(self, celsius: float):
        self._celsius = celsius

    @property
    def celsius(self) -> float:
        return self._celsius

    @celsius.setter
    def celsius(self, valor: float) -> None:
        if valor < -273.15:
            raise ValueError("Por debajo del cero absoluto")
        self._celsius = valor

    @property
    def fahrenheit(self) -> float:
        return self._celsius * 9/5 + 32

t = Temperatura(100)
print(t.fahrenheit)  # 212.0
t.celsius = 0
print(t.fahrenheit)  # 32.0

