static int CountWordOccurrences(List<string> strings, string word)
{
    int totalCount = 0;
    foreach (string str in strings)
    {
        string[] words = str.Split(' ');
        foreach (string w in words)
        {
            if (w.Equals(word, StringComparison.OrdinalIgnoreCase))
            {
                totalCount++;
            }
        }
    }
    return totalCount;
}
