### Solution:
```rust
use std::future::Future;
use std::pin::Pin;

struct ServiceRegistry {
    onstart: Vec<Pin<Box<dyn Future<Output = ()> + 'static>>>,
}

impl ServiceRegistry {
    fn new() -> Self {
        ServiceRegistry { onstart: Vec::new() }
    }

    fn register_service<F>(&mut self, fut: F)
    where
        F: Future<Output = ()> + 'static,
    {
        self.onstart.push(Box::pin(fut));
    }

    async fn start_services(&mut self) {
        for fut in &mut self.onstart {
            fut.await;
        }
    }
}

// Example usage
#[tokio::main]
async fn main() {
    let mut registry = ServiceRegistry::new();

    // Register services
    registry.register_service(async {
        println!("Service 1 started");
    });

    registry.register_service(async {
        println!("Service 2 started");
    });

    // Start all registered services
    registry.start_services().await;
