class DisjointSet:
    def __init__(self):
        self.parents = {}

    def find(self, element):
        if element not in self.parents:
            self.parents[element] = element
            return element
        if self.parents[element] != element:
            self.parents[element] = self.find(self.parents[element])
        return self.parents[element]

    def union(self, elementA, elementB):
        ancestorA = self.find(elementA)
        ancestorB = self.find(elementB)
        if ancestorA == ancestorB:
            return False
        self.parents[ancestorB] = ancestorA
        return True
```

