### Problem:
You are tasked with implementing a simple autocomplete feature for a search bar using a trie data structure. The autocomplete feature should suggest words based on the user's input prefix. You need to implement the `Trie` class and its associated methods to achieve this functionality.

The `Trie` class should have the following methods:
1. `insert(word: String)`: Inserts a word into the trie.
2. `search(word: String) -> Bool`: Returns true if the word is in the trie.
3. `startsWith(prefix: String) -> Bool`: Returns true if there is any word in the trie that starts with the given prefix.

You need to implement the `Trie` class and its methods to support the autocomplete feature.

### Solution:
```swift
class TrieNode {
    var children: [Character: TrieNode]
    var isEndOfWord: Bool

    init() {
        children = [Character: TrieNode]()
        isEndOfWord = false
    }
}

class Trie {
    private let root: TrieNode

    init() {
        root = TrieNode()
    }

    func insert(_ word: String) {
        var node = root
        for char in word {
            if let child = node.children[char] {
                node = child
            } else {
                let newNode = TrieNode()
                node.children[char] = newNode
                node = newNode
            }
        }
        node.isEndOfWord = true
    }

    func search(_ word: String) -> Bool {
        var node = root
        for char in word {
            guard let child = node.children[char] else { return false }
            node = child
        }
        return node.isEndOfWord
    }

    func startsWith(_ prefix: String) -> Bool {
        var node = root
        for char in prefix {
            guard let child = node.children[char] else { return false }
            node = child
        }
        return true
    }
}

// Example usage
let trie = Trie()
trie.insert("apple")
trie.insert("application")
trie.insert("app")
print(trie.search("apple")) // Output: true
print(trie.startsWith("app")) // Output: true
print(trie.search("apples")) // Output: false
```

