export class DisplayTemplateList1Item {
  @IsString()
  @IsNotEmpty()
  token!: string;

  @IsOptional()
  @ValidateNested()
  @Type(() => Image)
  image?: Image;

  @MainTextMaxLength(DISPLAY_TEMPLATE_ITEM_MAIN_TEXT_MAX_LENGTH)
  @ValidateNested()
  mainText: string;
