class ReturnOrder extends Model
{
    use HasFactory;

    protected $fillable = [
        'user_id',
        'payment_type',
        'payment_id',
        'paying_amount',
        'balance_transaction',
        'strip_order_id',
    ];

    public function calculateRefundAmount()
    {
        $refundAmount = 0;

        if ($this->payment_type === 'credit_card') {
            $refundAmount = $this->paying_amount * 0.9;
        } elseif ($this->payment_type === 'paypal') {
