import json

class Pet:
    def __init__(self, name, age, breed, available_for_adoption):
        self.name = name
        self.age = age
        self.breed = breed
        self.available_for_adoption = available_for_adoption

class PetSerializer:
    @staticmethod
    def serialize(pet):
        if isinstance(pet, Pet):
            return json.dumps({
                "name": pet.name,
                "age": pet.age,
                "breed": pet.breed,
