### Solution:
```csharp
using System;
using System.Collections.Generic;
using System.Linq;

public class Transaction
{
    public DateTime Date { get; set; }
    public decimal Amount { get; set; }
}

public class TransactionQuery
{
    public DateTime? StartDate { get; set; }
    public DateTime? EndDate { get; set; }
    public decimal? MinAmount { get; set; }
    public decimal? MaxAmount { get; set; }

    public List<Transaction> FilterTransactions(List<Transaction> transactions)
    {
        return transactions.Where(t =>
            (!StartDate.HasValue || t.Date >= StartDate) &&
            (!EndDate.HasValue || t.Date <= EndDate) &&
            (!MinAmount.HasValue || t.Amount >= MinAmount) &&
            (!MaxAmount.HasValue || t.Amount <= MaxAmount)
        ).ToList();
    }
}
