### Solution:
```csharp
// Import necessary libraries
using System;
using System.Security.Cryptography;
using System.Text;

public class UserRegistration
{
    public void RegisterUser(User user, CreateUserParams createUserParams, RegistrationSettings registrationSettings)
    {
        user.Record.NormalizedUserName = createUserParams.Username.ToLowerInvariant();
        user.Record.HashAlgorithm = "SHA1";
        SetPassword(user.Record, createUserParams.Password, registrationSettings);
    }

    private void SetPassword(UserRecord userRecord, string password, RegistrationSettings registrationSettings)
    {
        // Combine password with any additional registration settings for increased security
        string combinedPassword = password + registrationSettings?.AdditionalSettings;

        // Convert the combined password to a byte array
        byte[] passwordBytes = Encoding.UTF8.GetBytes(combinedPassword);

        // Create a new instance of the specified hash algorithm
        using (var hashAlgorithm = SHA1.Create())
        {
            // Compute the hash value of the password bytes
            byte[] hashBytes = hashAlgorithm.ComputeHash(passwordBytes);

            // Convert the hash bytes to a hexadecimal string
            string hashedPassword = BitConverter.ToString(hashBytes).Replace("-", "").ToLower();

            // Set the hashed password in the user record
            userRecord.HashedPassword = hashedPassword;
        }
    }
}

