public LiveData<List<JournalModel>> filterJournalsByCategory(LiveData<List<JournalModel>> items, String category) {
    MediatorLiveData<List<JournalModel>> filteredList = new MediatorLiveData<>();
    filteredList.addSource(items, journalModels -> {
        List<JournalModel> filtered = new ArrayList<>();
        for (JournalModel journal : journalModels) {
            if (journal.getCategory().equals(category)) {
                filtered.add(journal);
            }
        }
        filteredList.setValue(filtered);
    });
    return filteredList;
}
