### Problem:
You are tasked with implementing a Markdown to HTML converter in Swift. Markdown is a lightweight markup language with plain-text formatting syntax. Your task is to create a class `MarkdownConverter` with a method `convertToHTML` that takes a Markdown string as input and returns the corresponding HTML string.

The Markdown syntax to be supported includes:
- Headers: Lines starting with 1-6 hash symbols (#) represent headers of levels 1-6, respectively.
- Bold and Italic Text: Text enclosed in double asterisks (**) represents bold text, and text enclosed in underscores (_) represents italic text.
- Unordered Lists: Lines starting with a hyphen (-) represent unordered list items.
- Links: Text enclosed in square brackets ([]) followed by the URL in parentheses () represents a hyperlink.

Your `MarkdownConverter` class should have the following method:
```swift
class MarkdownConverter {
    func convertToHTML(_ markdown: String) -> String {
        // Your implementation here
    }
}
```

For example, given the input:
```markdown
# Header
This is a **bold** and _italic_ text.

- Unordered list item 1
- Unordered list item 2

[Link to Google](https://www.google.com)
```

The expected output would be:
```html
<h1>Header</h1>
<p>This is a <strong>bold</strong> and <em>italic</em> text.</p>
<ul>
  <li>Unordered list item 1</li>
  <li>Unordered list item 2</li>
</ul>
<a href="https://www.google.com">Link to Google</a>
```

### Solution:
```swift
class MarkdownConverter {
    func convertToHTML(_ markdown: String) -> String {
        var html = ""
        let lines = markdown.components(separatedBy: "\n")

        for line in lines {
            if line.starts(with: "#") {
                let headerLevel = line.prefix(while: { $0 == "#" }).count
                let headerText = line.trimmingCharacters(in: .whitespaces).dropFirst(headerLevel).trimmingCharacters(in: .whitespaces)
                html += "<h\(headerLevel)>\(headerText)</h\(headerLevel)>"
            } else if line.starts(with: "-") {
                html += "<ul><li>\(line.dropFirst().trimmingCharacters(in: .whitespaces))</li></ul>"
            } else if line.starts(with: "[") && line.contains("](") {
                let linkText = line[line.index(after: line.startIndex)..<line.firstIndex(of: "]")!]
                let linkURL = line[line.index(after: line.firstIndex(of: "(")!)..<line.firstIndex(of: ")")!]
                html += "<a href=\"\(linkURL)\">\(linkText)</a>"
            } else {
                var modifiedLine = line
                while modifiedLine.contains("**") {
                    if let start = modifiedLine.range(of: "**"), let end = modifiedLine[start.upperBound...].range(of: "**") {
                        let boldText = modifiedLine[start.upperBound..<end.lowerBound]
                        modifiedLine.replaceSubrange(start.lowerBound..<end.upperBound, with: "<strong>\(boldText)</strong>")
                    }
                }
                while modifiedLine.contains("_") {
                    if let start = modifiedLine.range(of: "_"), let end = modifiedLine[start.upperBound...].range(of: "_") {
                        let italicText = modifiedLine[start.upperBound..<end.lowerBound]
                        modifiedLine.replaceSubrange(start.lowerBound..<end.upperBound, with: "<em>\(italicText)</em>")
                    }
                }
                html += "<p>\(modifiedLine)</p>"
            }
        }

        return html
    }
}
```

