import Foundation

class NetworkLoggerPlugin: Plugin {
    func willSendRequest(_ request: URLRequest, target: TargetType) {
        if let url = request.url, let httpMethod = request.httpMethod, let headers = request.allHTTPHeaderFields {
            print("Request URL: \(url)")
            print("HTTP Method: \(httpMethod)")
            print("Request Headers: \(headers)")
