### Solution:
```csharp
public static class ExtensionMethods
{
    public static HtmlString RenderChecked(this object model, string property)
    {
        if (model != null)
        {
            var propertyValue = model.Reflection().GetPropertyValue(property);
            if (propertyValue is bool boolValue)
            {
                if (boolValue)
                {
                    return new HtmlString("<input type=\"checkbox\" checked=\"checked\" />");
                }
                else
                {
                    return new HtmlString("<input type=\"checkbox\" />");
                }
            }
            else
            {
                throw new ArgumentException("Property is not of type bool");
            }
        }
        else
        {
            throw new ArgumentNullException("model", "Model object cannot be null");
        }
    }
}
```

