```python
import requests

API_VERSION = "v1"

class TemplateManager:
    def __init__(self, base_url, api_key):
        self.base_url = base_url
        self.api_key = api_key

    def create_template(self, template_data):
        url = f"{self.base_url}/templates?api_version={API_VERSION}"
        headers = {"Authorization": f"Bearer {self.api_key}"}
        response = requests.post(url, json=template_data, headers=headers)
        return response.json()

    def update_template(self, template_id, updated_data):
        url = f"{self.base_url}/templates/{template_id}?api_version={API_VERSION}"
        headers = {"Authorization": f"Bearer {self.api_key}"}
        response = requests.put(url, json=updated_data, headers=headers)
        return response.json()

    def delete_template(self, template_id):
        url = f"{self.base_url}/templates/{template_id}?api_version={API_VERSION}"
        headers = {"Authorization": f"Bearer {self.api_key}"}
        response = requests.delete(url, headers=headers)
        return response.status_code == 204

    def get_template_by_id(self, template_id):
        url = f"{self.base_url}/templates/{template_id}?api_version={API_VERSION}"
        headers = {"Authorization": f"Bearer {self.api_key}"}
        response = requests.get(url, headers=headers)
        return response.json()
