### Solution:
```python
class Library:
    def __init__(self, books):
        self.books = books
        self.borrowed_books = {}

    def display_available_books(self):
        print("Available books:")
        for book in self.books:
            if book not in self.borrowed_books:
                print(book)
        print()

    def borrow_book(self, user, book):
        if book in self.books:
            if book in self.borrowed_books:
                print(f"{book} is already borrowed by {self.borrowed_books[book]}")
            else:
                self.borrowed_books[book] = user
                print(f"{book} has been borrowed by {user}")
        else:
            print(f"Sorry, {book} is not available in the library")

    def return_book(self, user, book):
        if book in self.borrowed_books and self.borrowed_books[book] == user:
            del self.borrowed_books[book]
            print(f"{book} has been returned by {user}")
        else:
            print(f"You have not borrowed {book}")

# Example usage
