interface AuthenticationProviderInterface {
    // Define the required methods for an authentication provider
}

class AuthenticationManager {
    private $providers = [];

    public function addProvider(AuthenticationProviderInterface $provider, $provider_id, $priority = 0, $global = FALSE) {
        $providerData = [
            'provider' => $provider,
            'priority' => $priority,
        ];

        if ($global) {
            $this->providers['global'][$provider_id] = $providerData;
        } else {
            $this->providers['non_global'][$provider_id] = $providerData;
        }

        // Sort the non-global providers based on priority
        uasort($this->providers['non_global'], function ($a, $b) {
            return $a['priority'] - $b['priority'];
        });
    }

    // Other methods for authentication management can be added here
}
```

