### Solution:
```java
import java.util.*;

class StudentCourseManager {
    private Map<String, Set<String>> studentCourses;

    public StudentCourseManager() {
        this.studentCourses = new HashMap<>();
    }

    public void addStudent(String studentName) {
        studentCourses.put(studentName, new HashSet<>());
    }

    public void enrollStudentCourse(String studentName, String course) {
        if (studentCourses.containsKey(studentName)) {
            studentCourses.get(studentName).add(course);
        } else {
            System.out.println("Student " + studentName + " does not exist.");
        }
    }

    public void removeStudentCourse(String course, String studentName) {
        if (studentCourses.containsKey(studentName)) {
            Set<String> courses = studentCourses.get(studentName);
            if (courses.contains(course)) {
                courses.remove(course);
            } else {
                System.out.println("Student " + studentName + " is not enrolled in " + course);
            }
        } else {
            System.out.println("Student " + studentName + " does not exist.");
        }
    }

    public void printState() {
        for (Map.Entry<String, Set<String>> entry : studentCourses.entrySet()) {
            System.out.println(entry.getKey() + ": " + String.join(", ", entry.getValue()));
        }
    }
}
```

