        return f"Device {self.serial_port} executed command: {command}"

class DeviceManager:
    def __init__(self):
        self.connections = {}

    def connect(self, device_id):
        if device_id in self.connections:
            return None  # Connection already exists
        else:
            try:
                subprocess.check_output(f"/usr/bin/ez-clang --connect={device_id}", shell=True)
                connection_id = str(hash(device_id))  # Generate unique connection ID
                self.connections[connection_id] = Device(device_id)
                return connection_id
