```

For example, if the input `supportedCipherSuites` array contains ["SSL_RSA_WITH_AES_128_CBC_SHA", "TLS_ECDHE_RSA_WITH_AES_256_GCM_SHA384"], the function should return ["SSL_RSA_WITH_AES_128_CBC_SHA", "TLS_RSA_WITH_AES_128_CBC_SHA", "TLS_ECDHE_RSA_WITH_AES_256_GCM_SHA384", "SSL_ECDHE_RSA_WITH_AES_256_GCM_SHA384"].

### Solution:
```java
import java.util.ArrayList;
import java.util.List;

public class CipherSuiteFilter {

    public String[] filterCipherSuites(String[] supportedCipherSuites) {
        List<String> filteredCipherSuites = new ArrayList<>();

        for (String cipherSuite : supportedCipherSuites) {
            filteredCipherSuites.add(cipherSuite);
            if (cipherSuite.startsWith("SSL_")) {
                filteredCipherSuites.add("TLS" + cipherSuite.substring(3));
            } else if (cipherSuite.startsWith("TLS_")) {
                filteredCipherSuites.add("SSL" + cipherSuite.substring(3));
            }
        }

        return filteredCipherSuites.toArray(new String[0]);
    }

