struct MessageSystem {
    messages: Vec<Message>,
}

impl MessageSystem {
    // Method to add a new message to the system
    fn add_message(&mut self, sender_id: u32, recipient_id: u32, label: String, timestamp: f64) {
        let message = Message {
            sender_id,
            recipient_id,
            label,
            timestamp,
        };
        self.messages.push(message);
    }

    // Method to retrieve all messages sent from a specific sender, sorted by timestamp
    fn get_messages_sent_by_sender(&self, sender_id: u32) -> Vec<&Message> {
        let mut sent_messages: Vec<&Message> = self.messages.iter()
            .filter(|message| message.sender_id == sender_id)
            .collect();
        sent_messages.sort_by(|a, b| a.timestamp.partial_cmp(&b.timestamp).unwrap());
