    callRecords: Map<string, number>; // Map to store call start times

    constructor() {
        this.callRecords = new Map();
    }

    // Enable or disable call monitoring
    setCallMonitoring(enable: boolean): void {
        this.callMonitoring = enable;
    }

    // Start tracking the duration of a call
    startCall(callId: string): void {
