class RendererManager
{
    private $renderers = [];

    /**
     * Adds a new renderer to the manager
     *
     * @param string $name Name of the renderer
     * @param mixed $renderer Renderer object
     * @return RendererManager Fluent interface
     */
    public function addRenderer($name, $renderer)
    {
