{
    #[Pure] public function __construct()
    {
        $this->code = "000";
        $this->message = "The inequalities matrix is empty";
    }
}

class InequalitiesMatrix
{
    private $matrix;

    public function __construct($n)
    {
        $this->matrix = array_fill(0, $n, array_fill(0, $n, 0));
    }

    public function setRelationship($i, $j, $relationship)
    {
        $this->matrix[$i][$j] = $relationship;
    }

    public function getRelationship($i, $j)
    {
        return $this->matrix[$i][$j];
    }

