    // Method to calculate the square of the length of the vector
    fn len_square(&self) -> f64 {
        self.x * self.x + self.y * self.y
    }
}

// Create the Lua bindings for the Vec2 struct
fn create_lua_bindings(lua: &Lua) -> Result<(), LuaError> {
    let globals = lua.globals();
    let table = lua.create_table()?;

