```csharp
using System;
using System.Reactive.Concurrency;
using System.Threading.Tasks;

public static class TaskDelayExtension
{
    public static Task<T> After<TArg1, TArg2, TArg3, TArg4, T>(TimeSpan duration, IScheduler scheduler, Func<TArg1, TArg2, TArg3, TArg4, Task<T>> value, TArg1 arg1, TArg2 arg2, TArg3 arg3, TArg4 arg4)
    {
        var delayedTask = Task.Delay(duration).ContinueWith(async _ =>
        {
            var result = await value(arg1, arg2, arg3, arg4).ConfigureAwait(false);
            return result;
        }, TaskContinuationOptions.ExecuteSynchronously);

        return delayedTask.Unwrap();
    }
}
