class ElementRenderer {
    private $attributes = [];

    public function add_render_attribute($element_id, $attribute, $value) {
        if (!isset($this->attributes[$element_id][$attribute])) {
            $this->attributes[$element_id][$attribute] = $value;
        } else {
            // If the attribute already exists, append the new value
            $this->attributes[$element_id][$attribute] .= ' ' . $value;
