### Solution:
```java
import java.util.Arrays;

public class DictionaryRowGroupBuilder {
    private byte[] byteSegments;
    private short[] shortSegments;
    private int[] integerSegments;

    public DictionaryRowGroupBuilder() {
        byteSegments = new byte[0];
        shortSegments = new short[0];
        integerSegments = new int[0];
    }

    public void appendByteSegments(byte[] segments) {
        byte[] newByteSegments = Arrays.copyOf(byteSegments, byteSegments.length + segments.length);
        System.arraycopy(segments, 0, newByteSegments, byteSegments.length, segments.length);
        byteSegments = newByteSegments;
    }

    public void appendShortSegments(short[] segments) {
        short[] newShortSegments = Arrays.copyOf(shortSegments, shortSegments.length + segments.length);
        System.arraycopy(segments, 0, newShortSegments, shortSegments.length, segments.length);
        shortSegments = newShortSegments;
    }

    public void appendIntegerSegments(int[] segments) {
        int[] newIntegerSegments = Arrays.copyOf(integerSegments, integerSegments.length + segments.length);
        System.arraycopy(segments, 0, newIntegerSegments, integerSegments.length, segments.length);
        integerSegments = newIntegerSegments;
    }

    public DictionaryRowGroup build(ColumnStatistics columnStatistics) {
        return new DictionaryRowGroup(byteSegments, shortSegments, integerSegments, columnStatistics);
    }
}
```
