```java
import java.io.IOException;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.Collection;

import ch.skymarshall.tcwriter.generators.model.persistence.JsonModelPersister;
import ch.skymarshall.tcwriter.generators.model.testapi.TestDictionary;
import ch.skymarshall.tcwriter.generators.visitors.ClassToDictionaryVisitor;

public class JavaToDictionary {

    private final Collection<Class<?>> tcClasses;

    public JavaToDictionary(Collection<Class<?>> tcClasses) {
        this.tcClasses = tcClasses;
    }

    public void convertToDictionary() {
        TestDictionary testDictionary = new TestDictionary();
        ClassToDictionaryVisitor visitor = new ClassToDictionaryVisitor(testDictionary);

        for (Class<?> tcClass : tcClasses) {
            visitor.visit(tcClass);
        }

        JsonModelPersister persister = new JsonModelPersister();
        Path dictionaryFilePath = Paths.get("test_dictionary.json");

        try {
            persister.saveModel(dictionaryFilePath, testDictionary);
            System.out.println("Dictionary successfully persisted to: " + dictionaryFilePath);
        } catch (IOException e) {
            System.err.println("Error persisting dictionary: " + e.getMessage());
        }
    }
}
```

