{
    public string PropertyName { get; set; }
    public object Value { get; set; }
}

public class AttributeValueMerger : IAttributeValueMerger
{
    public ResolvedPropertySetter MergeValues(ResolvedPropertySetter a, ResolvedPropertySetter b, out string error)
    {
        error = null;

        if (a == null && b == null)
