### Solution:
```python
class BankAccount:
    def __init__(self, account_number, initial_balance=0):
        self.account_number = account_number
        self.balance = initial_balance

    def deposit(self, amount):
        self.balance += amount

    def withdraw(self, amount):
        if amount > self.balance:
            return "Insufficient funds"
        else:
            self.balance -= amount
            return "Withdrawal successful"

    def check_balance(self):
        return self.balance

class BankingSystem:
    def __init__(self):
        self.accounts = {}

    def create_account(self, account_number):
        if account_number in self.accounts:
            return "Account already exists"
        else:
            self.accounts[account_number] = BankAccount(account_number)
            return "Account created successfully"

    def deposit_funds(self, account_number, amount):
        if account_number in self.accounts:
            self.accounts[account_number].deposit(amount)
            return "Deposit successful"
        else:
            return "Account does not exist"

    def withdraw_funds(self, account_number, amount):
        if account_number in self.accounts:
            return self.accounts[account_number].withdraw(amount)
        else:
            return "Account does not exist"

    def check_account_balance(self, account_number):
        if account_number in self.accounts:
            return self.accounts[account_number].check_balance()
        else:
            return "Account does not exist"

