signal1.send(3) // Output: 3
signal2.send(4) // Output: 4

// Dispose the observation
disposable.dispose()
```

### Solution:
```swift
func flattenSignals<T>(_ signals: [Signal<T>]) -> Signal<T> {
    let flattenedSignal = Signal<T>()
    var disposables: [Disposable] = []

    for signal in signals {
        let disposable = signal.observe { event in
            flattenedSignal.send(event)
        }
        disposables.append(disposable)
    }

    let disposable = Disposable()
    disposable.dispose = {
        for disposable in disposables {
            disposable.dispose()
        }
    }

    return flattenedSignal
}
```

