class KeyReservationSystem:
    def __init__(self):
        self.reserved_keys = {}

    def placeReservation(self, peerNodeId, keyId):
        if keyId is not None and keyId in self.reserved_keys:
            self.reserved_keys[keyId].add(peerNodeId)
        elif keyId is not None:
