class Lexeme:
    def __init__(self, pattern_id: int):
        self.pattern_id = pattern_id

class Lexer:
    def __init__(self, input_string: str):
        self.input_string = input_string
        self.current_position = 0

    def get_next_lexeme(self) -> Lexeme:
        if self.current_position >= len(self.input_string):
            return Lexeme(EOS_PATTERN_ID())

        current_char = self.input_string[self.current_position]
        if current_char in ['(', ')', '{', '}', '=', '<', ';']:
            self.current_position += 1
            return Lexeme(UNKNOWN_PATTERN_ID())

        # Tokenize known lexemes here
        # Example: check for keywords, identifiers, numbers, etc.

        # If no known lexeme is found, return unknown lexeme
        return Lexeme(UNKNOWN_PATTERN_ID())

