```php
interface ResponseFactoryInterface
{
    public function createResponse(int $statusCode, array $data = []): Response;
}

class Response
{
    private $statusCode;
    private $data;

    public function __construct($statusCode, $data = [])
    {
        $this->statusCode = $statusCode;
        $this->data = $data;
    }

