            new { Id = 2, Name = "Jane" }
        };

        var formatter = new NdjsonOutputFormatter();
        var context = new OutputFormatterWriteContext(
            new DefaultHttpContext(),
            new MemoryStream(),
            typeof(IEnumerable<object>),
            data
        );

        await formatter.WriteResponseBodyAsync(context, Encoding.UTF8);

