import java.math.BigDecimal;
import java.math.MathContext;

public class FactorialCalculator {
    public static BigDecimal b(double n) {
        return new BigDecimal(n, MathContext.DECIMAL128);
    }

    public static BigDecimal factorial(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("Input should be a non-negative integer");
        }

        BigDecimal result = b(1); // Initialize result to 1
        for (int i = 1; i <= n; i++) {
            result = result.multiply(b(i)); // Multiply result by i
        }
        return result;
    }
}
