Complete the `SlideInFromBottomAnimator` class by adding the following:
1. A `duration` property of type `TimeInterval` to specify the duration of the animation.
2. The `animateTransition(using:)` method to perform the actual animation based on the provided transition context.
3. The `isPresenting` property to determine whether the transition is presenting or dismissing a view controller.

Your implementation should ensure that the slide-in animation occurs from the bottom when pushing a new view controller onto the navigation stack and the slide-out animation occurs towards the bottom when popping a view controller from the stack.

### Solution:
```swift
import UIKit

public class SlideInFromBottomAnimator: NSObject, UIViewControllerAnimatedTransitioning {
    private let duration: TimeInterval
    public var isPresenting: Bool = true

    public init(duration: TimeInterval = 0.55) {
        self.duration = duration
    }

    public func transitionDuration(using transitionContext: UIViewControllerContextTransitioning?) -> TimeInterval {
        return duration
    }

    public func animateTransition(using transitionContext: UIViewControllerContextTransitioning) {
        guard let fromView = transitionContext.view(forKey: .from), let toView = transitionContext.view(forKey: .to) else {
            return
        }

        let containerView = transitionContext.containerView
        if isPresenting {
            containerView.addSubview(toView)
            toView.frame = CGRect(x: 0, y: containerView.bounds.height, width: containerView.bounds.width, height: containerView.bounds.height)
        } else {
            containerView.insertSubview(toView, belowSubview: fromView)
        }

        let initialFrame = isPresenting ? toView.frame : fromView.frame
        let finalFrame = isPresenting ? toView.frame : CGRect(x: 0, y: containerView.bounds.height, width: containerView.bounds.width, height: containerView.bounds.height)

        UIView.animate(withDuration: duration, animations: {
            if self.isPresenting {
                toView.frame = finalFrame
            } else {
                fromView.frame = finalFrame
            }
        }) { _ in
            let success = !transitionContext.transitionWasCancelled
            if !success {
                toView.removeFromSuperview()
            }
            transitionContext.completeTransition(success)
        }
    }
}
```

