import java.util.List;

public class BatchProcessor<T> {

  private final String container;

  private BatchProcessor(String container) {
    this.container = container;
  }

  public static <T> BatchProcessor<T> create(String container) {
    return new BatchProcessor<>(container);
  }

  public Unbatch<T> batch(List<T> data, int batchSize) {
