### Solution:
```swift
import UIKit

struct Item {
    let id: Int
    let name: String
}

class ItemService {
    func fetchItems(completion: @escaping ([Item]?) -> Void) {
        guard let url = URL(string: "https://api.example.com/items") else {
            completion(nil)
            return
        }

        URLSession.shared.dataTask(with: url) { data, response, error in
            guard let data = data, error == nil else {
                completion(nil)
                return
            }

            do {
                let itemsData = try JSONDecoder().decode([Item].self, from: data)
                completion(itemsData)
            } catch {
                completion(nil)
            }
        }.resume()
    }
}

class ViewController: UIViewController, UITableViewDataSource {
    var items: [Item] = []
    let itemService = ItemService()

    override func viewDidLoad() {
        super.viewDidLoad()
        // Assuming you have a UITableView instance named tableView
        tableView.dataSource = self
        itemService.fetchItems { [weak self] items in
            if let items = items {
                self?.items = items
                DispatchQueue.main.async {
                    self?.tableView.reloadData()
                }
            }
        }
    }

    func tableView(_ tableView: UITableView, numberOfRowsInSection section: Int) -> Int {
        return items.count
    }

    func tableView(_ tableView: UITableView, cellForRowAt indexPath: IndexPath) -> UITableViewCell {
        let cell = tableView.dequeueReusableCell(withIdentifier: "ItemCell", for: indexPath)
        let item = items[indexPath.row]
        cell.textLabel?.text = item.name
        return cell
    }
}
```

In this solution, the `ItemService` class contains the `fetchItems` function, which uses `URLSession` to make a network request to fetch the list of items from the server. The fetched data is then parsed using `JSONDecoder` and the completion handler is called with the array of `Item` objects.

The `ViewController` class adopts the `UITableViewDataSource` protocol to populate the table view with the fetched items. In the `viewDidLoad` method, it calls the `fetchItems` function of `ItemService` and updates the table view with the fetched items once the data is available.

