private static SonogramConfig ParametersToSonogramConfig(CommonParameters common) {
    SonogramConfig sonogramConfig = new SonogramConfig();
    sonogramConfig.setSampleRate(common.getSampleRate());
    sonogramConfig.setWindowSize(common.getWindowSize());
    sonogramConfig.setOverlap(common.getOverlap());
    sonogramConfig.setFftSize(common.getFftSize());

