  animate: boolean;
  className: string;
  variant: string;
  width: number;

  constructor(animate: boolean, className: string, variant: string, width: number) {
    this.animate = animate;
    this.className = className;
    this.variant = variant;
    this.width = width;
  }
}

function calculateTotalWidth(components: Component[]): number {
  let totalWidth = 0;

  for (const component of components) {
    let widthMultiplier = 1;
    if (component.variant === "text") {
      widthMultiplier = 2;
    } else if (component.variant === "image") {
      widthMultiplier = 3;
    }

    let componentWidth = component.width * widthMultiplier;
    if (component.animate) {
      componentWidth += 5;
    }

    totalWidth += componentWidth;
  }

  return totalWidth;
}

