### Solution:
```php
namespace App\Middleware;

use Psr\Http\Message\ServerRequestInterface as Request;
use Psr\Http\Server\RequestHandlerInterface as RequestHandler;
use Slim\Psr7\Response;

class MemberTokenMiddleware
{
    private $validTokens = ['valid_token_1', 'valid_token_2']; // Predefined list of valid member tokens

    public function __invoke(Request $request, RequestHandler $handler): Response
    {
        $authorizationHeader = $request->getHeaderLine('Authorization');

        if (!empty($authorizationHeader)) {
            $token = trim(str_replace('Bearer', '', $authorizationHeader));

            if (in_array($token, $this->validTokens)) {
                // Token is valid, allow the request to proceed
                return $handler->handle($request);
            }
        }

        // Token is invalid or not present, return 401 Unauthorized response
        $response = new Response();
        $response->getBody()->write('Unauthorized');
        return $response->withStatus(401);
    }
}
