import org.apache.commons.lang3.tuple.Pair;

import java.util.HashMap;
import java.util.Map;

public class MapFiller<K, V> {
    private Map<K, V> map;

    private MapFiller(Map<K, V> map) {
        this.map = map;
    }

    public static <K, V> MapFiller<K, V> from(Map<K, V> map) {
        return new MapFiller<>(map);
