### Solution:
```typescript
interface ProviderType {
  provide: string;
  useValue: any;
}

const IDEA_REPOSITORY = 'IDEA_REPOSITORY';

class DependencyInjector {
  private providers: ProviderType[];

  constructor(providers: ProviderType[]) {
    this.providers = providers;
  }

  resolve(token: string): any {
    const provider = this.providers.find((p) => p.provide === token);
    if (provider) {
      return provider.useValue;
    } else {
      throw new Error(`Dependency with token ${token} not found`);
    }
  }
}

