### Solution:
```java
public class CustomEncoder {

    private static final char[] DEFAULT_CHARS = {'a', 'b', 'c', 'd', 'e', 'f', 'g', 'h', 'i', 'j', 'k', 'l', 'm', 'n', 'o', 'p', 'q', 'r', 's', 't', 'u', 'v', 'w', 'x', 'y', 'z', '0', '1', '2', '3', '4', '5'};

    public String convertToCustomString(int number) {
        StringBuilder buffer = new StringBuilder();

        do {
            buffer.append(DEFAULT_CHARS[number % 32]);
            number = number >> 5;
        } while (number != 0);

        return buffer.toString();
    }
}
```

