using System;
using System.Collections.Generic;
using System.Linq;

public class Program
{
    public static int SumOfSquaresOfEvenNumbers(List<int> numbers)
    {
        int sum = numbers.Where(n => n % 2 == 0).Select(n => n * n).Sum();
        return sum;
    }

    public static void Main()
    {
        List<int> numbers1 = new List<int> { 1, 2, 3, 4, 5, 6 };
        List<int> numbers2 = new List<int> { 10, 11, 12, 13, 14, 15 };

