public class RefractiveIndexCalculator {
    private Map<Double, Double> refractiveIndexMedium;

    public RefractiveIndexCalculator() {
        refractiveIndexMedium = new HashMap<>();
        // Initialize the map with example wavelengths and their corresponding refractive indices
        refractiveIndexMedium.put(0.673, 1d);
        refractiveIndexMedium.put(0.818, 1d);
        refractiveIndexMedium.put(0.844, 1d);
        refractiveIndexMedium.put(1.313, 1d);
