import java.util.HashMap;
import java.util.Map;

public class BankAccount {
    private int accountNumber;
    private String accountHolderName;
    private double balance;

    public BankAccount(int accountNumber, String accountHolderName, double initialBalance) {
        this.accountNumber = accountNumber;
        this.accountHolderName = accountHolderName;
        this.balance = initialBalance;
    }

    public int getAccountNumber() {
        return accountNumber;
    }

    public String getAccountHolderName() {
        return accountHolderName;
    }

    public double getBalance() {
        return balance;
    }

    public void deposit(double amount) {
        balance += amount;
    }

    public boolean withdraw(double amount) {
        if (balance >= amount) {
            balance -= amount;
            return true;
        }
        return false; // Insufficient funds
    }
}

public class BankingSystem {
    private Map<Integer, BankAccount> accounts;
    private int accountNumberCounter;

    public BankingSystem() {
        accounts = new HashMap<>();
        accountNumberCounter = 1;
    }

    public int createAccount(String accountHolderName, double initialBalance) {
        int accountNumber = accountNumberCounter++;
        BankAccount newAccount = new BankAccount(accountNumber, accountHolderName, initialBalance);
        accounts.put(accountNumber, newAccount);
        return accountNumber;
    }

