public int MaxConsecutiveStates(State targetState)
{
    int maxConsecutive = 0;
    int currentConsecutive = 0;

    foreach (State state in states)
    {
        if (state == targetState)
        {
            currentConsecutive++;
            maxConsecutive = Math.Max(maxConsecutive, currentConsecutive);
