private function add(
    RequestInterface $request,
    ResponseInterface $response = null
) {
    $this->transactions[] = [
        'request'      => $request,
        'sent_request' => clone $request,
        'response'     => $response
    ];
    if (count($this->transactions) > $this->limit) {
        array_shift($this->transactions);
    }
}
