import android.content.Intent;
import android.net.ConnectivityManager;
import io.reactivex.Observable;
import io.reactivex.subjects.PublishSubject;

public class NetworkConnectivityMonitor {

    private PublishSubject<Intent> intentSubject = PublishSubject.create();

    public Observable<Intent> WhenIntentReceived(String intentAction) {
        return intentSubject.filter(intent -> intent.getAction().equals(intentAction));
    }

    public void startMonitoring() {
        // Simulate network connectivity changes
        new Thread(() -> {
            try {
                Thread.sleep(1000);
                Intent connectedIntent = new Intent(ConnectivityManager.CONNECTIVITY_ACTION);
                connectedIntent.putExtra(ConnectivityManager.EXTRA_NO_CONNECTIVITY, false);
                intentSubject.onNext(connectedIntent);

                Thread.sleep(1000);
                Intent disconnectedIntent = new Intent(ConnectivityManager.CONNECTIVITY_ACTION);
                disconnectedIntent.putExtra(ConnectivityManager.EXTRA_NO_CONNECTIVITY, true);
                intentSubject.onNext(disconnectedIntent);
            } catch (InterruptedException e) {
                intentSubject.onError(e);
            }
        }).start();
    }

    public static void main(String[] args) {
        NetworkConnectivityMonitor monitor = new NetworkConnectivityMonitor();
        Observable<Intent> connectivityChanges = monitor.WhenIntentReceived(ConnectivityManager.CONNECTIVITY_ACTION);
        connectivityChanges.subscribe(
                intent -> {
                    boolean isConnected = !intent.getBooleanExtra(ConnectivityManager.EXTRA_NO_CONNECTIVITY, false);
                    System.out.println("Network connectivity change received. Connected: " + isConnected);
                },
                error -> {
                    System.err.println("Error occurred: " + error.getMessage());
                }
        );

        monitor.startMonitoring();
    }
}
```

