import javax.servlet.RequestDispatcher;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import java.io.IOException;

public class WebServerRouter {
    public void routeRequest(String urlPath, HttpServletRequest request, HttpServletResponse response) throws IOException {
        switch (urlPath) {
            case "/home":
                forwardRequest("/static/HTML/employeeHomepage.html", request, response);
                break;
            case "/profile":
                forwardRequest("/static/HTML/Profile.html", request, response);
                break;
            case "/editProf":
                forwardRequest("/static/HTML/editProf.html", request, response);
                break;
            case "/about":
                forwardRequest("/static/HTML/about.html", request, response);
                break;
            case "/contact":
                forwardRequest("/static/HTML/contact.html", request, response);
                break;
            case "/dashboard":
                forwardRequest("/static/HTML/dashboard.html", request, response);
                break;
            default:
                // Handle unknown URL paths
                response.sendError(HttpServletResponse.SC_NOT_FOUND);
        }
    }

    private void forwardRequest(String target, HttpServletRequest request, HttpServletResponse response) throws IOException {
        RequestDispatcher dispatcher = request.getRequestDispatcher(target);
        dispatcher.forward(request, response);
    }
}
