```python
class Parameter:
    def __init__(self, name, Type, Value=None):
        self.name = name
        self.Type = Type
        self.Value = Value

class ParameterError(Exception):
    pass

class Config:
    def __init__(self):
        self.parameters = {}

    def set_parameter(self, name, value):
        if name not in self.parameters:
            raise ParameterError(f"Parameter '{name}' does not exist")
        if not isinstance(value, self.parameters[name].Type):
            raise TypeError(f"Invalid type for parameter '{name}'. Expected {self.parameters[name].Type.__name__}, got {type(value).__name__}")
        self.parameters[name].Value = value

    def get_parameter(self, name):
        if name not in self.parameters:
            raise ParameterError(f"Parameter '{name}' does not exist")
        return self.parameters[name].Value
```

