### Solution:
```python
import subprocess

def check_tmux_installed():
    return subprocess.call(['which', 'tmux'], stdout=subprocess.DEVNULL, stderr=subprocess.STDOUT) == 0

class TerminalManager:
    def __init__(self):
        self.sessions = {}

    def create_session(self, session_name):
        if session_name not in self.sessions:
            self.sessions[session_name] = f"Created new session: {session_name}"
        else:
            return f"Session '{session_name}' already exists"

    def switch_session(self, session_name):
        if session_name in self.sessions:
            return f"Switched to session: {session_name}"
        else:
            return f"Session '{session_name}' does not exist"

    def list_sessions(self):
        return list(self.sessions.keys())

if check_tmux_installed():
    terminal_manager = TerminalManager()
    while True:
        command = input("Enter command: ").split()
        if command[0] == 'create':
            print(terminal_manager.create_session(command[1]))
        elif command[0] == 'switch':
            print(terminal_manager.switch_session(command[1]))
        elif command[0] == 'list':
            print(terminal_manager.list_sessions())
        elif command[0] == 'exit':
            break
        else:
            print("Invalid command")
else:
    print("tmux is not installed on this system")
```
